import { useEffect, useRef, useState } from "react";
import { ComponentPicker } from "../features/catalog/ComponentPicker";
import type { CartLine } from "../features/catalog/ComponentPicker";
import type { CatalogRow } from "../features/catalog/useCatalog";

// Dev-only performance harness for the component picker: loads the local
// fixture file generated by scripts/generate-fake-components.mjs (never
// Supabase) so scroll/search responsiveness can be checked with a
// realistic row count. Only reachable when running `npm run dev` — see
// router.tsx, which only registers this route when import.meta.env.DEV.
export function PickerBench() {
  const [items, setItems] = useState<CatalogRow[] | null>(null);
  const [error, setError] = useState(false);
  const [cart, setCart] = useState<Record<string, CartLine>>({});
  const renderStart = useRef(performance.now());
  const [renderMs, setRenderMs] = useState<number | null>(null);

  useEffect(() => {
    renderStart.current = performance.now();
    fetch("/dev-data/fake-components.json")
      .then((res) => {
        if (!res.ok) throw new Error("not found");
        return res.json();
      })
      .then((data) => {
        setItems(data as CatalogRow[]);
        setRenderMs(performance.now() - renderStart.current);
      })
      .catch(() => setError(true));
  }, []);

  if (error) {
    return (
      <div>
        No fixture data found. Run <code>node scripts/generate-fake-components.mjs</code> first.
      </div>
    );
  }

  if (!items) {
    return <div>Loading fixture data...</div>;
  }

  return (
    <div>
      <h1>Picker bench</h1>
      <p>
        {items.length} fake rows · loaded in {renderMs?.toFixed(1)}ms · {Object.keys(cart).length}{" "}
        selected
      </p>
      <ComponentPicker items={items} cart={cart} onChange={setCart} />
    </div>
  );
}
